        "path": "atelier-lulua-trainer/Program.cs",
        "content": "using System;\nusing System.Threading;\nusing AtelierLuluaTrainer.Core;\n\nnamespace AtelierLuluaTrainer\n{\n    class Program\n    {\n        static void Main(string[] args)\n        {\n            Console.WriteLine(\"Atelier Lulua: The Scion of Arland Trainer v1.0\");\n            Console.WriteLine(\"================================================\");\n            Console.WriteLine(\"Make sure the game process is running.\");\n\n            var trainer = new TrainerController();\n            trainer.AttachToGame();\n\n            if (!trainer.IsAttached)\n            {\n                Console.WriteLine(\"Failed to attach to Atelier Lulua process. Exiting.\");\n                return;\n            }\n\n            Console.WriteLine(\"Attached successfully. Hotkeys:\");\n            Console.WriteLine(\"  F1 - Toggle Infinite HP\");\n            Console.WriteLine(\"  F2 - Toggle Infinite MP\");\n            Console.WriteLine(\"  F3 - Toggle Max Money\");\n            Console.WriteLine(\"  F4 - Toggle Max Alchemy Level\");\n            Console.WriteLine(\"  F5 - Toggle Max Friendship\");\n            Console.WriteLine(\"  ESC - Exit\");\n\n            while (true)\n            {\n                if (Console.KeyAvailable)\n                {\n                    var key = Console.ReadKey(true).Key;\n                    switch (key)\n                    {\n                        case ConsoleKey.F1:\n                            trainer.ToggleCheat(CheatType.InfiniteHP);\n                            break;\n                        case ConsoleKey.F2:\n                            trainer.ToggleCheat(CheatType.InfiniteMP);\n                            break;\n                        case ConsoleKey.F3:\n                            trainer.ToggleCheat(CheatType.MaxMoney);\n                            break;\n                        case ConsoleKey.F4:\n                            trainer.ToggleCheat(CheatType.MaxAlchemyLevel);\n                            break;\n                        case ConsoleKey.F5:\n                            trainer.ToggleCheat(CheatType.MaxFriendship);\n                            break;\n                        case ConsoleKey.Escape:\n                            Console.WriteLine(\"Exiting trainer...\");\n                            return;\n                    }\n                }\n                Thread.Sleep(50);\n            }\n        }\n    }\n}\n"
    },
