        "path": "atelier-lulua-trainer/Core/TrainerController.cs",
        "content": "using System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.Runtime.InteropServices;\n\nnamespace AtelierLuluaTrainer.Core\n{\n    /// <summary>\n    /// Core trainer controller that manages memory reading/writing for Atelier Lulua.\n    /// Uses Windows API for process memory manipulation.\n    /// </summary>\n    public class TrainerController\n    {\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int nSize, out int lpNumberOfBytesRead);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool WriteProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int nSize, out int lpNumberOfBytesWritten);\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool CloseHandle(IntPtr hObject);\n\n        private const uint PROCESS_ALL_ACCESS = 0x1F0FFF;\n\n        private IntPtr _processHandle;\n        private Process _gameProcess;\n        private Dictionary<CheatType, bool> _cheatStates;\n\n        /// <summary>\n        /// Memory addresses for Atelier Lulua: The Scion of Arland (Steam v1.0).\n        /// These are example offsets; in a real trainer they would be dynamically resolved.\n        /// </summary>\n        private static class MemoryOffsets\n        {\n            public static readonly IntPtr BaseAddress = new IntPtr(0x00A3F000); // Example base\n            public static readonly int HPOffset = 0x1C0;\n            public static readonly int MPOffset = 0x1C4;\n            public static readonly int MoneyOffset = 0x2A0;\n            public static readonly int AlchemyLevelOffset = 0x3E4;\n            public static readonly int FriendshipOffset = 0x4B0;\n        }\n\n        public bool IsAttached => _processHandle != IntPtr.Zero;\n\n        public TrainerController()\n        {\n            _cheatStates = new Dictionary<CheatType, bool>\n            {\n                { CheatType.InfiniteHP, false },\n                { CheatType.InfiniteMP, false },\n                { CheatType.MaxMoney, false },\n                { CheatType.MaxAlchemyLevel, false },\n                { CheatType.MaxFriendship, false }\n            };\n        }\n\n        /// <summary>\n        /// Attaches to the Atelier Lulua game process.\n        /// </summary>\n        public void AttachToGame()\n        {\n            var processes = Process.GetProcessesByName(\"AtelierLulua\");\n            if (processes.Length == 0)\n            {\n                Console.WriteLine(\"Game process not found. Make sure 'AtelierLulua.exe' is running.\");\n                return;\n            }\n\n            _gameProcess = processes[0];\n            _processHandle = OpenProcess(PROCESS_ALL_ACCESS, false, _gameProcess.Id);\n\n            if (_processHandle == IntPtr.Zero)\n            {\n                Console.WriteLine(\"Failed to open process. Try running as administrator.\");\n            }\n        }\n\n        /// <summary>\n        /// Toggles a specific cheat on/off.\n        /// </summary>\n        public void ToggleCheat(CheatType cheat)\n        {\n            if (!IsAttached) return;\n\n            _cheatStates[cheat] = !_cheatStates[cheat];\n            bool enabled = _cheatStates[cheat];\n            Console.WriteLine($\"{cheat}: {(enabled ? \"Enabled\" : \"Disabled\")}\");\n\n            if (enabled)\n            {\n                ApplyCheat(cheat);\n            }\n        }\n\n        /// <summary>\n        /// Applies the cheat effect based on type.\n        /// </summary>\n        private void ApplyCheat(CheatType cheat)\n        {\n            byte[] buffer;\n            int bytesWritten;\n            IntPtr address = _gameProcess.MainModule.BaseAddress + (int)MemoryOffsets.BaseAddress;\n\n            switch (cheat)\n            {\n                case CheatType.InfiniteHP:\n                    buffer = BitConverter.GetBytes(9999); // Max HP value\n                    WriteProcessMemory(_processHandle, address + MemoryOffsets.HPOffset, buffer, buffer.Length, out bytesWritten);\n                    break;\n\n                case CheatType.InfiniteMP:\n                    buffer = BitConverter.GetBytes(999);\n                    WriteProcessMemory(_processHandle, address + MemoryOffsets.MPOffset, buffer, buffer.Length, out bytesWritten);\n                    break;\n\n                case CheatType.MaxMoney:\n                    buffer = BitConverter.GetBytes(999999);\n                    WriteProcessMemory(_processHandle, address + MemoryOffsets.MoneyOffset, buffer, buffer.Length, out bytesWritten);\n                    break;\n\n                case CheatType.MaxAlchemyLevel:\n                    buffer = BitConverter.GetBytes(50); // Max level\n                    WriteProcessMemory(_processHandle, address + MemoryOffsets.AlchemyLevelOffset, buffer, buffer.Length, out bytesWritten);\n                    break;\n\n                case CheatType.MaxFriendship:\n                    buffer = BitConverter.GetBytes(100); // Max friendship value\n                    WriteProcessMemory(_processHandle, address + MemoryOffsets.FriendshipOffset, buffer, buffer.Length, out bytesWritten);\n                    break;\n            }\n        }\n\n        /// <summary>\n        /// Cleans up the process handle.\n        /// </summary>\n        public void Dispose()\n        {\n            if (_processHandle != IntPtr.Zero)\n            {\n                CloseHandle(_processHandle);\n                _processHandle = IntPtr.Zero;\n            }\n        }\n    }\n}\n"
    },
