        "path": "atelier-lulua-trainer/Core/CheatType.cs",
        "content": "namespace AtelierLuluaTrainer.Core\n{\n    /// <summary>\n    /// Enum representing the available cheat types for Atelier Lulua trainer.\n    /// </summary>\n    public enum CheatType\n    {\n        /// <summary>\n        /// Set HP to maximum (9999).\n        /// </summary>\n        InfiniteHP,\n\n        /// <summary>\n        /// Set MP to maximum (999).\n        /// </summary>\n        InfiniteMP,\n\n        /// <summary>\n        /// Set money to maximum (999999).\n        /// </summary>\n        MaxMoney,\n\n        /// <summary>\n        /// Set alchemy level to maximum (50).\n        /// </summary>\n        MaxAlchemyLevel,\n\n        /// <summary>\n        /// Set friendship with all characters to maximum (100).\n        /// </summary>\n        MaxFriendship\n    }\n}\n"
