        "path": "atelier-lulua-trainer/Core/MemoryScanner.cs",
        "content": "using System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.Runtime.InteropServices;\n\nnamespace AtelierLuluaTrainer.Core\n{\n    /// <summary>\n    /// Utility class for scanning memory to find dynamic addresses (AOB scanning).\n    /// Useful for future-proofing against game updates.\n    /// </summary>\n    public class MemoryScanner\n    {\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool VirtualQueryEx(IntPtr hProcess, IntPtr lpAddress, out MEMORY_BASIC_INFORMATION lpBuffer, int dwLength);\n\n        [StructLayout(LayoutKind.Sequential)]\n        private struct MEMORY_BASIC_INFORMATION\n        {\n            public IntPtr BaseAddress;\n            public IntPtr AllocationBase;\n            public uint AllocationProtect;\n            public IntPtr RegionSize;\n            public uint State;\n            public uint Protect;\n            public uint Type;\n        }\n\n        private IntPtr _processHandle;\n\n        public MemoryScanner(IntPtr processHandle)\n        {\n            _processHandle = processHandle;\n        }\n\n        /// <summary>\n        /// Scans process memory for a given byte pattern (AOB).\n        /// </summary>\n        /// <param name=\"pattern\">Byte pattern to find, e.g., new byte[] { 0x90, 0x90, 0xCC }</param>\n        /// <param name=\"mask\">Mask string where 'x' means match, '?' means wildcard, e.g., \"xx?\"</param>\n        /// <returns>List of addresses where pattern is found.</returns>\n        public List<IntPtr> ScanPattern(byte[] pattern, string mask)\n        {\n            var results = new List<IntPtr>();\n            IntPtr currentAddress = IntPtr.Zero;\n\n            while (true)\n            {\n                MEMORY_BASIC_INFORMATION mbi;\n                int mbiSize = Marshal.SizeOf(typeof(MEMORY_BASIC_INFORMATION));\n\n                if (VirtualQueryEx(_processHandle, currentAddress, out mbi, mbiSize) == false)\n                    break;\n\n                // Only scan committed, readable memory regions\n                if (mbi.State == 0x1000 && (mbi.Protect & 0x04) != 0) // MEM_COMMIT, PAGE_READWRITE\n                {\n                    byte[] buffer = new byte[(int)mbi.RegionSize];\n                    int bytesRead;\n\n                    if (ReadProcessMemory(_processHandle, mbi.BaseAddress, buffer, buffer.Length, out bytesRead))\n                    {\n                        for (int i = 0; i <= bytesRead - pattern.Length; i++)\n                        {\n                            bool match = true;\n                            for (int j = 0; j < pattern.Length; j++)\n                            {\n                                if (mask[j] == 'x' && buffer[i + j] != pattern[j])\n                                {\n                                    match = false;\n                                    break;\n                                }\n                            }\n                            if (match)\n                            {\n                                results.Add(mbi.BaseAddress + i);\n                            }\n                        }\n                    }\n                }\n\n                // Move to next region\n                long nextAddress = (long)mbi.BaseAddress + (long)mbi.RegionSize;\n                currentAddress = new IntPtr(nextAddress);\n            }\n\n            return results;\n        }\n\n        [DllImport(\"kernel32.dll\", SetLastError = true)]\n        private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int nSize, out int lpNumberOfBytesRead);\n    }\n}\n"
    },
