        "path": "atelier-lulua-trainer/tests/TrainerControllerTests.cs",
        "content": "using System;\nusing System.Diagnostics;\nusing AtelierLuluaTrainer.Core;\nusing Xunit;\n\nnamespace AtelierLuluaTrainer.Tests\n{\n    /// <summary>\n    /// Unit tests for TrainerController. Since memory manipulation requires a running game process,\n    /// these tests focus on state management and error handling.\n    /// </summary>\n    public class TrainerControllerTests\n    {\n        [Fact]\n        public void TrainerController_InitialState_IsNotAttached()\n        {\n            // Arrange & Act\n            var controller = new TrainerController();\n\n            // Assert\n            Assert.False(controller.IsAttached);\n        }\n\n        [Fact]\n        public void ToggleCheat_WhenNotAttached_DoesNotThrow()\n        {\n            // Arrange\n            var controller = new TrainerController();\n\n            // Act & Assert (should not throw)\n            var exception = Record.Exception(() => controller.ToggleCheat(CheatType.InfiniteHP));\n            Assert.Null(exception);\n        }\n\n        [Fact]\n        public void AttachToGame_WhenGameNotRunning_DoesNotAttach()\n        {\n            // Arrange\n            var controller = new TrainerController();\n\n            // Act\n            controller.AttachToGame();\n\n            // Assert\n            Assert.False(controller.IsAttached);\n        }\n\n        [Fact]\n        public void CheatType_EnumValues_AreCorrect()\n        {\n            // Arrange & Act\n            var values = Enum.GetValues(typeof(CheatType));\n\n            // Assert\n            Assert.Equal(5, values.Length);\n            Assert.Contains(CheatType.InfiniteHP, values);\n            Assert.Contains(CheatType.InfiniteMP, values);\n            Assert.Contains(CheatType.MaxMoney, values);\n            Assert.Contains(CheatType.MaxAlchemyLevel, values);\n            Assert.Contains(CheatType.MaxFriendship, values);\n        }\n\n        [Fact]\n        public void MemoryScanner_NullHandle_DoesNotThrowOnConstruction()\n        {\n            // Arrange & Act\n            var scanner = new MemoryScanner(IntPtr.Zero
